  });
  await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'networkidle' });
  await page.selectOption('#traceSelect', { index: 1 }).catch(async () => {
    const opts = await page.$$eval('#traceSelect option', os => os.map(o => o.value).filter(Boolean));
    if (opts[0]) await page.selectOption('#traceSelect', opts[0]);
  });
  await page.click('#loadBtn');
  await page.waitForFunction(() => document.body.classList.contains('results-available') || document.body.classList.contains('playback-ready'), { timeout: 180000 });
  await page.waitForTimeout(500);
  // Select DOTS compare
  const dots = page.locator('#headerBaselineAlgoRow .baseline-algo-pill[data-algo="dots"]');
  await dots.click();
  await page.waitForTimeout(200);
  const info = await page.evaluate(() => {
    const run = document.getElementById('headerBaselineRunBtn');
    const strip = document.querySelector('.header-baseline');
    const rect = strip?.getBoundingClientRect();
    return {
      runHidden: run?.hidden,
      runDisabled: run?.disabled,
      runText: run?.textContent,
      stripHeight: rect ? Math.round(rect.height) : null,
      scrollWidth: document.documentElement.scrollWidth,
      clientWidth: document.documentElement.clientWidth,
      stripScroll: strip ? strip.scrollWidth > strip.clientWidth : null,
    };
  });
  console.log('1280', JSON.stringify(info));
  await page.screenshot({ path: 'web/usability/desktop-compare-header-run-1280-live.png', fullPage: false });

  await page.setViewportSize({ width: 900, height: 800 });
  await page.waitForTimeout(200);
  const info900 = await page.evaluate(() => {
    const run = document.getElementById('headerBaselineRunBtn');
    const strip = document.querySelector('.header-baseline');
    const rect = strip?.getBoundingClientRect();
    const header = document.querySelector('header');
    return {
      runHidden: run?.hidden,
      runDisabled: run?.disabled,
      runText: run?.textContent,
      stripHeight: rect ? Math.round(rect.height) : null,
      headerHeight: header ? Math.round(header.getBoundingClientRect().height) : null,
      scrollWidth: document.documentElement.scrollWidth,
      clientWidth: document.documentElement.clientWidth,
    };
  });
  console.log('900', JSON.stringify(info900));
  await page.screenshot({ path: 'web/usability/desktop-compare-header-run-900-live.png', fullPage: false });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
